<?php declare(strict_types=1);session_name('googa');session_start();require_once __DIR__.'/lib/store.php';require_once __DIR__.'/lib/version.php';$context=googa_session_context();googa_require_parent($context);if(empty($_SESSION['googa_social_csrf']))$_SESSION['googa_social_csrf']=bin2hex(random_bytes(24));$v=googa_app_version();?><!doctype html><html lang="no"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Googa – Lær sammen</title><link rel="stylesheet" href="styles.css?v=<?=rawurlencode($v)?>"><style>body{margin:0;padding:16px;background:linear-gradient(145deg,#effbfa,#fff5d9);font-family:Nunito,sans-serif;color:#123b59}.shell{width:min(680px,100%);margin:auto}.card{margin:12px 0;padding:22px;border-radius:24px;background:#fffdf7;box-shadow:0 16px 38px #123b5918}.back{color:#123b59;font-weight:900;text-decoration:none}.eyebrow{color:#087f89;font-size:12px;font-weight:900;letter-spacing:.1em}.switch{display:flex;justify-content:space-between;gap:14px;align-items:center}.switch button,.copy,.remove{border:0;border-radius:13px;padding:12px 15px;font:900 15px Nunito;cursor:pointer}.switch button,.copy{background:#087f89;color:#fff}.switch button.off{background:#9baeb7}.goal{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;background:#effafa;padding:15px;border-radius:17px}.goal b{font-size:29px}.invite{display:flex;gap:8px}.invite input{min-width:0;flex:1;border:1px solid #cadce1;border-radius:12px;padding:10px;font:inherit}.connection{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #e5edf0}.remove{background:#fff0ee;color:#8b2e22}@media(max-width:520px){body{padding:10px}.card{padding:18px}.invite{flex-wrap:wrap}.invite .copy{width:100%}}</style><main class="shell"><a class="back" href="family.php">← Familie</a><section class="card"><p class="eyebrow">TRYGT LÆRINGSSAMMEN</p><h1>Lær sammen</h1><p>Ingen barn kan søke etter andre, sende meldinger eller vises offentlig.</p><div class="switch"><span><b>Sosial læring</b><br><small>Privat ukesmål for familien</small></span><button id="toggle" type="button">Laster …</button></div></section><section class="card"><h2>Familieuken</h2><div class="goal"><span>Fullfør 5 brett sammen denne uka.<br><small>Alle i familien teller. Ingen blir rangert.</small></span><b id="goal">0 / 5</b></div></section><section class="card"><h2>Godkjente familier</h2><p>Kun foreldre kan legge til eller fjerne familier. Dette åpner ikke chat eller synlighet for barna.</p><div class="invite"><input id="code" placeholder="Lim inn familiekode"><button class="copy" id="connect" type="button">Legg til</button></div><button class="copy" id="make" type="button" style="margin-top:10px">Lag familiekode</button><p id="made"></p><div id="connections"></div></section></main><script>const csrf=<?=json_encode($_SESSION['googa_social_csrf'])?>;async function api(a,d){let o={credentials:'same-origin',cache:'no-store'};if(d){o.method='POST';o.headers={'Content-Type':'application/x-www-form-urlencoded'};o.body=new URLSearchParams({...d,csrf})}return(await fetch('family-social-api.php?action='+a,o)).json()}function draw(d){toggle.textContent=d.enabled?'På – slå av':'Av – slå på';toggle.className=d.enabled?'':'off';goal.textContent=d.done+' / '+d.goal;connections.innerHTML=d.connections.length?d.connections.map((x,i)=>'<div class="connection"><span>Godkjent familie '+(i+1)+'</span><button class="remove" data-id="'+x.id+'">Fjern</button></div>').join(''):'<p><small>Ingen godkjente familier ennå.</small></p>';connections.querySelectorAll('button').forEach(b=>b.onclick=async()=>{await api('remove',{id:b.dataset.id});load()})}async function load(){draw(await api('status'))}toggle.onclick=async()=>{const d=await api('status');await api('toggle',{enabled:d.enabled?'':'1'});load()};make.onclick=async()=>{const d=await api('invite',{});made.textContent='Del denne familiekoden med en annen forelder: '+d.inviteToken};connect.onclick=async()=>{if(!code.value.trim())return;await api('connect',{token:code.value.trim()});code.value='';load()};load();</script></html>
